# Generate a short visual description for an image using Anthropic Claude\nimport os\n\n# Anthropic SDK for natural language generation\nfrom anthropic import Anthropic\n\nclass DescribeImage:\n    \"\"\"Generate a concise visual description of an image.\n    \"\"\"\n    @staticmethod\n    def generate_description(image_path: str) -> str:\n        \"\"\"Create a short caption for the supplied image.\n        Args:\n            image_path (str): Path to the image file.\n        Returns:\n            str: Human‑readable visual description.\n        \"\"\"\n        # Instantiate the SDK – the API key is read from the environment\n        client = Anthropic(api_key=os.getenv("ANTHROPIC_API_KEY"))\n        # Call the model (claude-3-5-sonnet-20240620 is used as the concrete model)\n        response = client.messages.create(\n            model=\"claude-3-5-sonnet-20240620\",\n            # Anthropic requires base64‑encoded image input for vision tasks\n            images=[open(image_path, \"rb\").read()],\n            max_tokens=200,\n            temperature=0.2,\n        )\n        # The response contains a text message with the description\n        description = response.message.content[0].text\n        return description.strip()\n\n# Local helper utilities (loaded in VisionClient)\n# -----------------------------------------------------------------------------\n# Configuration loading and client helpers defined in vision_client.py (separate file)\n# -----------------------------------------------------------------------------
